@import "tailwindcss";
@source "../../components";
@source "../../features";
@import "./public-compat.css";
@import "./public-motion.css";
@import "../../features/financial-health-check/styles/print.css";

/*
====================================
CCPun global foundation

Ownership:
- tokens/theme/document defaults live here
- cross-feature compatibility classes live in components/styles/public-compat.css
- shared named animations/reduced-motion live in components/styles/public-motion.css
- feature-only global contracts stay with their feature owner
- Website 4.3 visual rules belong in its CSS Modules, not in this file
====================================
*/

/* ── 1. CSS Custom Properties (raw HSL channels) ── */
:root {
  color-scheme: dark;
  --background: 0 15% 18%;
  --foreground: 0 10% 98%;
  --card: 0 15% 15%;
  --card-foreground: 0 10% 98%;
  --popover: 0 15% 15%;
  --popover-foreground: 0 10% 98%;
  --primary: 45 60% 70%;
  --primary-foreground: 0 15% 12%;
  --secondary: 0 12% 26%;
  --secondary-foreground: 0 10% 98%;
  --muted: 0 12% 26%;
  --muted-foreground: 0 10% 70%;
  --accent: 45 60% 70%;
  --accent-foreground: 0 15% 12%;
  --destructive: 0 60% 60%;
  --destructive-foreground: 0 10% 98%;
  --border: 0 12% 32%;
  --input: 0 12% 26%;
  --ring: 45 60% 70%;
  --radius: 1rem;
}

/* ── 2. Tailwind v4 Theme ── */
@theme inline {
  --color-background:           hsl(var(--background));
  --color-foreground:           hsl(var(--foreground));
  --color-card:                 hsl(var(--card));
  --color-card-foreground:      hsl(var(--card-foreground));
  --color-popover:              hsl(var(--popover));
  --color-popover-foreground:   hsl(var(--popover-foreground));
  --color-primary:              hsl(var(--primary));
  --color-primary-foreground:   hsl(var(--primary-foreground));
  --color-secondary:            hsl(var(--secondary));
  --color-secondary-foreground: hsl(var(--secondary-foreground));
  --color-muted:                hsl(var(--muted));
  --color-muted-foreground:     hsl(var(--muted-foreground));
  --color-accent:               hsl(var(--accent));
  --color-accent-foreground:    hsl(var(--accent-foreground));
  --color-destructive:          hsl(var(--destructive));
  --color-destructive-foreground: hsl(var(--destructive-foreground));
  --color-border:               hsl(var(--border));
  --color-input:                hsl(var(--input));
  --color-ring:                 hsl(var(--ring));

  --color-navy-900: hsl(0 20% 12%);
  --color-navy-800: hsl(0 15% 18%);
  --color-navy-700: hsl(0 12% 26%);
  --color-gold-400: hsl(45 65% 78%);
  --color-gold-500: hsl(45 60% 70%);
  --color-gold-600: hsl(45 55% 60%);

  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);

  --font-sans: 'Kanit', system-ui, sans-serif;

  --shadow-glass:   0 8px 32px rgba(0,0,0,0.3), inset 0 1px 0 rgba(255,255,255,0.1);
  --shadow-gold:    0 4px 24px rgba(197,160,89,0.4);
  --shadow-gold-lg: 0 8px 32px rgba(197,160,89,0.5);

  --animate-fade-in:    fade-in 0.6s ease-out forwards;
  --animate-fade-in-up: fade-in-up 0.8s ease-out forwards;
  --animate-scale-in:   scale-in 0.5s ease-out forwards;
  --animate-float:      float 6s ease-in-out infinite;
  --animate-pulse-glow: pulse-glow 2s ease-in-out infinite;
  --animate-shimmer:    shimmer 2s linear infinite;
  --animate-scroll-breath: scroll-breath 2.4s cubic-bezier(0.16, 1, 0.3, 1) infinite;
}

/* ── 3. Document foundation ── */
@layer base {
  * {
    border-color: hsl(var(--border));
  }

  html {
    scroll-behavior: smooth;
    scroll-padding-top: 80px;
    overflow-x: clip;
  }

  body {
    background-color: hsl(var(--background));
    color: hsl(var(--foreground));
    font-family: 'Kanit', system-ui, sans-serif;
    font-size: 1rem;
    font-weight: 300;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    overflow-x: clip;
  }

  :focus-visible {
    outline: 3px solid #e0c985;
    outline-offset: 3px;
  }
}

/* Admin skip link is intentionally global because Web and Admin share the root stylesheet. */
.admin-skip-link {
  position: fixed;
  left: 1rem;
  top: 1rem;
  z-index: 100;
  min-height: 44px;
  padding: 0.65rem 1rem;
  border-radius: 0.75rem;
  background: #e0c985;
  color: #251818;
  font-weight: 600;
  transform: translateY(-200%);
  transition: transform 150ms ease-out;
}

.admin-skip-link:focus {
  transform: translateY(0);
}

/* Readability baseline retained only for the reachable shared glass-card primitive. */
.glass-card .text-xs {
  font-size: 0.8125rem;
  line-height: 1.55;
}

.glass-card .text-sm {
  font-size: 0.9375rem;
  line-height: 1.6;
}

@media (min-width: 768px) {
  .glass-card .text-xs {
    font-size: 0.875rem;
  }
}

/* Global document scrollbar. Feature scroll containers own their own scrollbar rules. */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: hsl(0,45%,6%); }
::-webkit-scrollbar-thumb { background: hsl(0,30%,22%); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: hsl(42,50%,55%); }
